package com.thymeandtable.service;
import com.thymeandtable.db.DatabaseConnection; import com.thymeandtable.model.*; import java.sql.*; import java.util.*;
public class PantryService {
 public List<PantryItem> list(User u)throws SQLException{List<PantryItem> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT pi.id,i.name,pi.quantity,pi.unit,COALESCE(pi.expiry_date,'') expiry_date FROM pantry_items pi JOIN ingredients i ON i.id=pi.ingredient_id WHERE pi.user_id=? ORDER BY i.name")){p.setInt(1,u.getId());try(ResultSet r=p.executeQuery()){while(r.next())out.add(new PantryItem(r.getInt(1),r.getString(2),r.getDouble(3),r.getString(4),r.getString(5)));}}return out;}
 public String save(User u,String name,double qty,String unit,String expiry)throws SQLException{if(name==null||name.trim().length()<2||name.length()>80)return "Enter a valid ingredient name.";if(qty<0||qty>100000)return "Quantity must be between 0 and 100000.";if(unit==null||unit.trim().isEmpty()||unit.length()>12)return "Enter a valid unit.";try(Connection c=DatabaseConnection.getConnection()){try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO ingredients(name,unit) VALUES(?,?)")){p.setString(1,name.trim());p.setString(2,unit.trim());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO pantry_items(user_id,ingredient_id,quantity,unit,expiry_date) VALUES(?,(SELECT id FROM ingredients WHERE name=?),?,?,?) ON CONFLICT(user_id,ingredient_id) DO UPDATE SET quantity=excluded.quantity,unit=excluded.unit,expiry_date=excluded.expiry_date")){p.setInt(1,u.getId());p.setString(2,name.trim());p.setDouble(3,qty);p.setString(4,unit.trim());p.setString(5,expiry==null||expiry.isBlank()?null:expiry);p.executeUpdate();}return "";}}
 public void delete(User u,int id)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM pantry_items WHERE id=? AND user_id=?")){p.setInt(1,id);p.setInt(2,u.getId());p.executeUpdate();}}
}
